package com.stayhaven.repo; import com.stayhaven.domain.LoyaltyTransaction; import org.springframework.data.jpa.repository.*; import java.util.*;
public interface LoyaltyTransactionRepository extends JpaRepository<LoyaltyTransaction,Long>{@EntityGraph(attributePaths={"guest","booking"}) List<LoyaltyTransaction> findAllByOrderByCreatedAtDesc();boolean existsByBookingIdAndType(Long id,String type);@org.springframework.transaction.annotation.Transactional void deleteByBookingId(Long id);@Query("select coalesce(sum(t.points),0) from LoyaltyTransaction t where t.guest.id=:id") long balance(@org.springframework.data.repository.query.Param("id") Long id);}
